  pointCard.querySelector('.card-body').append($('otherPoints'));$('otherPoints').hidden=true;otherCard.remove();
  const receive=document.createElement('section');receive.className='card dashboard-receive-card';receive.innerHTML='<div class="card-head"><h2>Receive MIO Points</h2></div><div class="card-body"><small>Your member code</small><strong id="dashboardReceiveCode" class="code">—</strong><button class="btn small copy-code" id="dashboardCopyCode" data-copy="">Copy member code</button><p>Share this code with the sender. Existing package transfer rules apply.</p></div>';$('page-transfer').prepend(receive);
  const walletHub=document.createElement('div');walletHub.id='incomeWalletHub';$('page-wallet').prepend(walletHub);
  const profile=document.createElement('div');profile.id='dashboardProfile';$('page-profile').append(profile);
  const securityBody=$('page-security')?.querySelector('.card-body');if(securityBody&&!$('transactionPinForm')){securityBody.insertAdjacentHTML('beforeend','<hr class="dashboard-divider"><div class="transaction-pin-card"><h2 id="transactionPinHeading">Set transaction PIN</h2><p class="helper">A 4–6 digit PIN is required for MIO transfers and package activation.</p><form id="transactionPinForm" class="stack-form"><div id="transactionPinChangeVerification" class="transaction-pin-change-verification" hidden><p class="helper">For security, verify your previous PIN or current authenticator code.</p><label>Verification method<select id="transactionPinVerificationMethod"><option value="pin">Previous transaction PIN</option><option value="totp">Authenticator code</option></select></label><label id="transactionPinPreviousWrap">Previous transaction PIN<input id="transactionPinPrevious" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="current-password" placeholder="Current PIN"></label><label id="transactionPinTotpWrap" hidden>Current authenticator code<input id="transactionPinTotp" type="text" inputmode="numeric" minlength="6" maxlength="6" pattern="[0-9]{6}" autocomplete="one-time-code" placeholder="6-digit code"></label></div><label>New transaction PIN<input id="transactionPin" name="pin" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" required autocomplete="new-password" placeholder="4–6 digits"></label><label>Confirm PIN<input id="transactionPinConfirm" name="confirm" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" required autocomplete="new-password" placeholder="Repeat PIN"></label><button class="btn primary" id="transactionPinSave" type="submit">Save transaction PIN</button><small id="transactionPinStatus" class="helper" role="status"></small></form></div>');}
  if(!$('transactionPinDialog')){document.body.insertAdjacentHTML('beforeend','<dialog id="transactionPinDialog" class="transaction-pin-dialog"><form id="transactionPinDialogForm" class="transaction-pin-dialog-card"><div class="transaction-pin-dialog-icon">'+icon('shield')+'</div><div><span class="transaction-pin-kicker">Secure transaction</span><h2 id="transactionPinDialogTitle">Set your transaction PIN</h2><p id="transactionPinDialogMessage">Create a private 4–6 digit PIN before continuing.</p></div><label>Transaction PIN<input id="transactionPinDialogValue" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="new-password" required placeholder="4–6 digits"></label><label id="transactionPinDialogConfirmWrap">Confirm PIN<input id="transactionPinDialogConfirm" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="new-password" placeholder="Repeat PIN"></label><p id="transactionPinDialogStatus" class="helper" role="alert"></p><div class="transaction-pin-actions"><button class="btn" type="button" id="transactionPinDialogCancel">Cancel</button><button class="btn primary" type="submit" id="transactionPinDialogSubmit">Set transaction PIN</button></div></form></dialog>');}
  const transferForm=$('transferForm');if(transferForm&&!$('transferPin')){const wrap=document.createElement('label');wrap.className='transfer-pin-field';wrap.innerHTML='Transaction PIN<input id="transferPin" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="current-password" placeholder="Enter PIN when requested">';const submit=transferForm.querySelector('button[type="submit"],button');if(submit)transferForm.insertBefore(wrap,submit);else transferForm.append(wrap);}
  $('transactionPinVerificationMethod')?.addEventListener('change',e=>{const totp=e.target.value==='totp';$('transactionPinPreviousWrap').hidden=totp;$('transactionPinTotpWrap').hidden=!totp;$('transactionPinPrevious').required=transactionPinConfigured&&!totp;$('transactionPinTotp').required=transactionPinConfigured&&totp});
  $('transactionPinForm')?.addEventListener('submit',async e=>{e.preventDefault();const wasConfigured=transactionPinConfigured,pin=$('transactionPin')?.value||'',confirm=$('transactionPinConfirm')?.value||'',status=$('transactionPinStatus'),button=$('transactionPinSave');status.textContent='';if(pin!==confirm){status.textContent='The PINs do not match.';return}button.disabled=true;let result;if(!wasConfigured){result=await api.rpc('set_transaction_pin',{p_pin:pin})}else{const method=$('transactionPinVerificationMethod').value;if(method==='totp'){try{await api.verifyAuthenticator($('transactionPinTotp').value.trim())}catch(error){button.disabled=false;status.textContent=error.message||'Authenticator verification failed.';return}result=await api.rpc('change_transaction_pin',{p_new_pin:pin,p_current_pin:null})}else result=await api.rpc('change_transaction_pin',{p_new_pin:pin,p_current_pin:$('transactionPinPrevious').value})}button.disabled=false;if(result.error){status.textContent=result.error.message||'The transaction PIN could not be saved.';return}setTransactionPinConfigured(true);e.target.reset();$('transactionPinVerificationMethod').dispatchEvent(new Event('change'));status.textContent=wasConfigured?'Transaction PIN updated securely.':'Transaction PIN saved.'});
  $('transactionPinDialogForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,mode=form.dataset.mode||'verify',pin=$('transactionPinDialogValue').value,status=$('transactionPinDialogStatus');status.textContent='';if(mode==='setup'){const confirm=$('transactionPinDialogConfirm').value;if(pin!==confirm){status.textContent='The PINs do not match.';return}const button=$('transactionPinDialogSubmit');button.disabled=true;const result=await api.rpc('set_transaction_pin',{p_pin:pin});button.disabled=false;if(result.error){status.textContent=result.error.message||'The PIN could not be saved.';return}setTransactionPinConfigured(true);closePinDialog('__configured__');return}closePinDialog(pin)});
  $('transactionPinDialogCancel')?.addEventListener('click',()=>closePinDialog(null));
  const nav=document.querySelector('.top .nav');let dashboard=nav.querySelector('[data-page="dashboard"]');if(!dashboard){dashboard=document.createElement('button');dashboard.dataset.page='dashboard';dashboard.textContent='My Dashboard';nav.append(dashboard)}
  $('page-dashboard').innerHTML='<div class="dashboard-loading">Loading your account overview…</div>';
