  $('dashboardGeneralNotifications').onclick=async()=>{const list=$('dashboardGeneralNotificationList'),orders=$('dashboardNotificationList');list.hidden=!list.hidden;orders.hidden=true;$('dashboardGeneralNotifications').setAttribute('aria-expanded',String(!list.hidden));$('dashboardNotifications').setAttribute('aria-expanded','false');if(!list.hidden&&Number(generalNotifications?.unread)){await api.rpc('mark_notifications_read');generalNotifications.unread=0;renderGeneralNotifications()}};
  const syncHeaderOffset=()=>{const header=document.querySelector('body>.top,.top');document.documentElement.style.setProperty('--account-header-offset',`${Math.max(0,Math.round(header?.getBoundingClientRect().height||0))}px`)};syncHeaderOffset();window.addEventListener('resize',syncHeaderOffset,{passive:true});if(window.ResizeObserver){const header=document.querySelector('body>.top,.top');if(header)new ResizeObserver(syncHeaderOffset).observe(header)}renderOrderNotifications();
