 function renderAccountNav(){const target=$('memberAccountNav');if(!target)return;target.setAttribute('aria-label','My dashboard');const sections=[['Overview',[['dashboard','My Dashboard'],['profile','My profile'],['network','My network']]],['Finance',[['earnings','Earnings'],['wallet','My wallet'],['transfer','Transfer MIO'],['transactions','Transaction history']]],['Marketplace',[['ecommerce','E-commerce'],['orders','My orders'],['packages','Membership plans']]],['Account',[['security','Security'],...(authState.sellers?[['seller','Seller centre']]:[]),...(authState.sellOpen?[['sell','Sell with us']]:[]),...(authState.admin?[['workspace','Admin Dashboard']]:[])]]];target.innerHTML=sections.filter(([,links])=>links.length).map(([label,links])=>`<section class="member-nav-group"><p>${label}</p>${links.map(([id,text])=>`<button type="button" data-page="${id}" ${id==='workspace'?'id="dashboardAdminNav"':''} class="${currentPage===id?'active':''}">${icon(icons[id])}<span>${text}</span></button>`).join('')}</section>`).join('')}
