 function metric(label,value,sub,art,detail){const tag=detail?'button':'div';return `<${tag} class="dashboard-metric" ${detail?`type="button" data-dashboard-detail="${detail}"`:''}><span class="dashboard-metric-icon">${icon(art)}</span><div><span>${label}</span><strong>${number(value)}</strong><small>${sub}${detail?' ↗':''}</small></div></${tag}>`}
 function maintenanceTime(due){const total=due?Math.max(0,new Date(due).getTime()-(Date.now()+serverOffset)):0;return{total,days:Math.floor(total/86400000),hours:Math.floor(total/3600000)%24,minutes:Math.floor(total/60000)%60,seconds:Math.floor(total/1000)%60}}
 function maintenanceCountdown(kind,due){const value=maintenanceTime(due);return `<span class="maintenance-countdown" data-maintenance-countdown="${kind}" role="timer" aria-label="${value.days} days, ${value.hours} hours, ${value.minutes} minutes and ${value.seconds} seconds remaining"><span><b data-time-part="days">${String(value.days).padStart(3,'0')}</b><small>Days</small></span><i>:</i><span><b data-time-part="hours">${String(value.hours).padStart(2,'0')}</b><small>Hours</small></span><i>:</i><span><b data-time-part="minutes">${String(value.minutes).padStart(2,'0')}</b><small>Minutes</small></span><i>:</i><span><b data-time-part="seconds">${String(value.seconds).padStart(2,'0')}</b><small>Seconds</small></span></span>`}
 function maintenanceCard(kind){const m=maintenanceStatus||{},monthly=kind==='monthly',due=m[`${kind}_due_at`],time=maintenanceTime(due),active=!!m[`${kind}_active`]&&time.total>0,rules=m.rules||{},progress=Number(m.monthly_progress_ppv)||0,target=Number(m.monthly_required_ppv)||0;if(!m.rules?.enabled||!due)return `<div class="dashboard-future dashboard-maintenance-card maintenance-unavailable"><span class="dashboard-future-icon">${icon('lock')}</span><div><h3>${monthly?'Monthly':'Annual'} maintenance</h3><small>Activate a package to start</small></div></div>`;return `<details class="dashboard-future dashboard-maintenance-card ${active?'is-active':'is-expired'}"><summary><span class="maintenance-card-heading"><span class="dashboard-future-icon">${icon('clock')}</span><span><h3>${monthly?'Monthly':'Annual'} maintenance</h3><small data-maintenance-status="${kind}">${active?'Active countdown':'Renewal due'} · Open details</small></span></span>${maintenanceCountdown(kind,due)}</summary><div class="maintenance-card-details">${monthly?`<p>${number(progress,2)} / ${number(target,2)} PPV towards the next 30 days. ${number((rules.monthly_levels||{})[m.package]||0,0)} earning generations for your package.</p><p>Choose Shopping Points for up to 50% of products, or pay in advance with Cash Wallet MIO, or use COD. COD requires a refundable 2 MIO guarantee. Maintenance shopping rewards go to the eligible network after delivery and payment confirmation.</p><button type="button" class="btn primary small" data-maintenance-shop>Shop for maintenance</button>`:`<p>${number(rules.annual_fee_mio||20,2)} MIO from Cash Wallet. ${number(Number(rules.annual_company_rate||0)*100,0)}% company fee; the rest follows the configured network generations.</p><p>Current deadline: ${date(due)}. Renewal adds 365 days to your remaining time.</p><button type="button" class="btn primary small" data-annual-maintenance>Renew for ${number(rules.annual_fee_mio||20,2)} MIO</button>`}</div></details>`}
