 function communityShareCard(c={}){const rules=c.rules||{},actual=Number(c.active_actual_shares)||0,gift=Number(c.active_gift_shares)||0,total=Number.isFinite(Number(c.active_total_shares))?Number(c.active_total_shares):actual+gift,nextShare=Math.max(1,Number(c.next_actual_share)||Number(c.lifetime_actual_shares||0)+1),directTarget=Math.max(1,Number(c.next_required_directs)||nextShare*(Number(rules.directs_per_share)||5)),dpTarget=Math.max(1,Number(c.next_required_dp)||nextShare*(Number(rules.dp_per_share)||500)),packagePct=c.eligible_package?100:0,directPct=Math.min(100,100*(Number(c.directs)||0)/directTarget),dpPct=Math.min(100,100*(Number(c.direct_dp)||0)/dpTarget),enabled=c.enabled!==false&&rules.enabled!==false,pct=enabled?Math.max(0,Math.min(100,(packagePct+directPct+dpPct)/3)):0,currentCycle=Number(c.current_cycle)||0,nextCycle=Number(c.next_cycle)||currentCycle+1,grants=Array.isArray(c.grants)?c.grants:[],activeGrants=grants.filter(g=>Number(g.start_cycle)<=nextCycle&&Number(g.end_cycle)>=nextCycle),status=!enabled?'Program unavailable':total>0?`${number(total,0)} active share${total===1?'':'s'}`:c.eligible_package?'In progress':'Not qualified',lifecycle=activeGrants.length?activeGrants.map((g,i)=>{const start=Number(g.start_cycle)||nextCycle,end=Number(g.end_cycle)||start,remaining=Math.max(0,end-Math.max(nextCycle,start)+1),qty=Number(g.quantity)||0,kind=String(g.kind||'actual').replace(/^./,x=>x.toUpperCase());return `<article><div><span>${esc(kind)} share${qty===1?'':'s'}</span><strong>${number(qty,0)} share${qty===1?'':'s'} · ${number(remaining,0)} distribution${remaining===1?'':'s'} remaining</strong></div><small>Cycle ${number(start,0)}–${number(end,0)}</small></article>`}).join(''):'<p class="community-empty">No active shares yet. Complete the qualification above to unlock your first share.</p>';return `<details class="dashboard-panel community-share-card"><summary><div><span class="manager-summary-kicker">Community Share Qualification</span><h2>${esc(status)}</h2><p>${total>0?`Progress towards actual share ${number(nextShare,0)}`:`Progress towards your first active share`}</p></div><div class="manager-summary-progress"><div class="manager-progress"><span style="width:${pct}%"></span></div><strong data-community-share-progress>${number(pct,2)}%</strong></div></summary><div class="community-share-details"><div class="community-share-overview"><div><span>Actual</span><strong>${number(actual,0)}</strong></div><div><span>Gift</span><strong>${number(gift,0)}</strong></div><div><span>Total active</span><strong data-community-share-total>${number(total,0)}</strong></div></div><div class="community-qualification">${progressMini('Eligible package',api.planName(c.package),api.planName(rules.minimum_package||'ADVANCED_2'),packagePct)}${progressMini('Direct sponsors',number(c.directs,0),number(directTarget,0),directPct)}${progressMini('Direct Points',number(c.direct_dp,2),number(dpTarget,2),dpPct)}</div><section class="community-share-lifecycle"><div class="dashboard-panel-title"><div><h3>Active share duration</h3><p>Each successful admin distribution uses one remaining cycle.</p></div><b>Next cycle ${number(nextCycle,0)}</b></div>${lifecycle}</section></div></details>`}
